		public global::System.Collections.Generic.List<global::Dpr.SequenceEditor.CommandParam> GetCommandParams() {
			if (_cachedCommandParams.IsNullOrEmpty())
			{
				_cachedCommandParams = new List<CommandParam>(1024);
				foreach (var group in _groupData)
				{
					if (group.Commands == null)
						continue;

					foreach (var command in group.Commands)
					{
						var commandParam = new CommandParam
						{
							Group = group,
							IsAlreadyCalled = false,
							CommandNo = command.Macro.CommandNo,
							StartFrame = command.StartFrame,
							EndFrame = command.EndFrame,
							GroupNo = group.GrpNo,
							GroupOption = group.GroupOption,
							Macro = Cast(command.Macro),
						};
						commandParam.Macro.CamFile = command.Macro.CamFile;
						if (commandParam.Macro.CommandNo == CommandNo.SpecialChainAttakDefine)
							HasChainAttack = true;

						_cachedCommandParams.Add(commandParam);
					}
				}
			}

			var commandParams = new List<CommandParam>(_cachedCommandParams.Count);
			foreach (var commandParam in _cachedCommandParams)
				commandParams.Add(new CommandParam(commandParam));

			return commandParams;
		}
